def transform(grid):
    from collections import Counter
    from math import gcd

    h, w = len(grid), len(grid[0])

    # The separator color makes repeated, nearly uniform grid lines.
    line_score = Counter()
    for row in grid:
        counts = Counter(row)
        color, n = counts.most_common(1)[0]
        if n / w >= 0.7:
            line_score[color] += n / w
    for c in range(w):
        counts = Counter(grid[r][c] for r in range(h))
        color, n = counts.most_common(1)[0]
        if n / h >= 0.7:
            line_score[color] += n / h
    separator = line_score.most_common(1)[0][0]

    line_rows = [
        r for r in range(h)
        if sum(v == separator for v in grid[r]) / w >= 0.7
    ]
    line_cols = [
        c for c in range(w)
        if sum(grid[r][c] == separator for r in range(h)) / h >= 0.7
    ]

    interior = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if r not in line_rows and c not in line_cols
    )
    fill = interior.most_common(1)[0][0]

    marks = [
        (r, c) for r in range(h) for c in range(w)
        if grid[r][c] not in (separator, fill)
    ]
    if not marks:
        return [[fill]]

    def coords(vals):
        vals = sorted(set(vals))
        step = 0
        for a, b in zip(vals, vals[1:]):
            step = gcd(step, b - a)
        if step == 0:
            step = 1
        return list(range(vals[0], vals[-1] + 1, step))

    rows = coords(r for r, _ in marks)
    cols = coords(c for _, c in marks)

    out = []
    for i in range(len(rows) - 1):
        row = []
        for j in range(len(cols) - 1):
            corners = [
                grid[rows[i]][cols[j]],
                grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]],
                grid[rows[i + 1]][cols[j + 1]],
            ]
            value = corners[0]
            if value in (separator, fill) or not all(x == value for x in corners):
                value = fill
            row.append(value)
        out.append(row)
    return out or [[fill]]
